import base64
import json
import logging

import requests
from requests.packages.urllib3.exceptions import InsecureRequestWarning

from taf.fdsw.rc.clients.data import ClientData
from taf.fdsw.rc.clients.exceptions import (ClientAuthenticationFailed,
                                            ClientConnectionFailed,
                                            ClientNotConnected,
                                            ClientRequestFailed)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RCHttpClient():
    DEFAULT_API_ENDPOINT = "/dnr/api/"
    DEFAULT_API_VERSION = "1.1"
    DEFAULT_SCHEMA_VERSION = "2.0"
    _URL_COMPOSITION = "{protocol}://{ip}:{port}{api_endpoint}{api_version}"
    _REQUEST_ID_COMPOSITION = "{auth_token}:{base_request_id}"

    def __init__(self, ip_address, port, username, password, api_version=DEFAULT_API_VERSION,
                 api_schema_version=DEFAULT_SCHEMA_VERSION, api_endpoint=DEFAULT_API_ENDPOINT, secure=True):
        requests.packages.urllib3.disable_warnings(InsecureRequestWarning)
        if secure:
            self.http_protocol = "https"
        else:
            self.http_protocol = "http"
        self.ip_address = ip_address
        self.port = port
        self.username = username
        self.password = password
        self.api_url = self._URL_COMPOSITION.format(
            protocol=self.http_protocol,
            ip=self.ip_address,
            port=self.port,
            api_endpoint=api_endpoint,
            api_version=api_version
        )
        self.headers = {'Content-type': 'application/json'}
        self.auth_token = None
        self._api_schema_version = api_schema_version
        self._last_base_request_id = 1

    @property
    def is_connected(self):
        if self.auth_token is None:
            return False
        else:
            return True

    def connect(self):
        logger.debug("Acquiring access token")
        try:
            auth_response = self.send(
                method="login",
                parameters={
                    "username": self.username,
                    "password": self.password
                },
            )
        except ClientRequestFailed as e:
            raise ClientAuthenticationFailed(str(e))
        logger.info(
            "Got response: result={} , error={}".format(auth_response.data, auth_response.error))
        if not isinstance(auth_response.data, dict):
            err_msg = "Endpoint provided inconsistent authentication data {}"
            raise ClientAuthenticationFailed(err_msg.format(auth_response.data))

        auth_token = auth_response.data.get("authToken")

        if auth_token is None:
            raise ClientAuthenticationFailed("Endpoint did not provide authentication token")

        self.auth_token = auth_token
        logger.debug("Authentication successful")

    def __handle_response(self, response):

        if response.status_code != requests.codes.ok:
            err_msg = "Client request failed with status {status} and message {msg}"
            raise ClientRequestFailed(err_msg.format(
                status=response.status_code,
                msg=response.text)
            )

        try:
            if 'application/json' in response.headers['Content-Type']:
                json_response_data = response.json()
                payload = None
            else:
                json_response_data = json.loads(base64.b64decode(response.headers['X-Message-Header']))
                payload = response.content
        except ValueError as e:
            err_msg = "Data returned by endpoint is inconsistent or faulty, DATA: {data} , ERROR: {error}"
            raise ClientRequestFailed(err_msg.format(
                data=response.text,
                error=e
            ))
        result_data = json_response_data.get("result")
        error_data = json_response_data.get("error")
        payload_data = payload if payload else None
        logger.info(
            "Got response: result={} , error={}".format(result_data, error_data))
        application_data = ClientData(data=result_data, error=error_data, payload=payload_data)

        return application_data

    def __get_request_id(self, method=None):
        if method == "login":
            return "1"

        if not self.is_connected:
            raise ClientNotConnected("Client is not connected to the endpoint")

        self._last_base_request_id = self._last_base_request_id + 1

        return self._REQUEST_ID_COMPOSITION.format(
            auth_token=self.auth_token,
            base_request_id=self._last_base_request_id
        )

    def __prepare_request(self, method, parameters):
        request_id = self.__get_request_id(method)

        request = {
            "id": request_id,
            "method": method,
            "params": parameters,
            "jsonrpc": self._api_schema_version
        }
        return request

    @staticmethod
    def __encode_request(request):
        return base64.b64encode(json.dumps(request).encode())

    def send(self, method, parameters, timeout=10):

        request = self.__prepare_request(method, parameters)
        logger.info(
            "Executing request: method={} , params={}".format(method, parameters))
        try:
            response = requests.post(self.api_url, json=request, headers=self.headers,
                                     timeout=timeout, verify=False)
        except requests.exceptions.RequestException as rq_e:
            raise ClientConnectionFailed("Client connection to endpoint failed with error {}".format(rq_e))

        return self.__handle_response(response=response)

    def send_file(self, file_data, method, parameters, timeout):
        headers = self._prepare_headers(method, parameters)
        try:
            response = requests.post(self.api_url, data=file_data, timeout=timeout, headers=headers, verify=False)
        except requests.exceptions.RequestException as rq_e:
            raise ClientConnectionFailed("Client connection to endpoint failed with error {}".format(rq_e))
        return self.__handle_response(response)

    def get_stream(self, method, parameters, timeout):
        headers = self._prepare_headers(method, parameters)
        logger.info(
            "Executing request: method={} , params={}".format(method, parameters))
        try:
            response = requests.post(self.api_url, timeout=timeout, headers=headers, verify=False)
        except requests.exceptions.RequestException as rq_e:
            raise ClientConnectionFailed("Client connection to endpoint failed with error {}".format(rq_e))
        return self.__handle_data_stream(response)

    def _prepare_headers(self, method, parameters):
        request = self.__prepare_request(method, parameters)
        request_encoded = self.__encode_request(request)
        headers = {'Content-type': 'application/octet-stream',
                   "X-Message-Header": request_encoded}
        return headers

    def __handle_data_stream(self, response):
        if response.status_code != requests.codes.ok:
            err_msg = "Client request failed with status {status} and message {msg}"
            raise ClientRequestFailed(err_msg.format(
                status=response.status_code,
                msg=response.text)
            )
        application_data = response.text.encode()
        return application_data

    def disconnect(self):
        self.auth_token = None
